insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('a4792192-98aa-5cd4-acce-a891dbc9edfb', 'rg8-word-parts-p01', (select id from public.skills where slug = 'read-g8-word-parts'), null,
        '6-8', $q$Night at the Observatory$q$, $q$Every October, the Riverside Middle School astronomy club holds a night at the county observatory. This year, Mateo Alvarez was in charge of the portable telescope, a small instrument that two students could carry across the parking lot without help.

Before anyone could look at the sky, Ms. Haddad asked Mateo to inspect each lens for dust. He checked them carefully under a flashlight, because even a tiny smudge could blur the view of a faraway planet.

The evening was spectacular. Through the eyepiece, Saturn appeared as a pale gold ball with a thin ring around it, and several students gasped out loud. A crowd of spectators from the neighborhood lined up behind the club members, waiting for their own turn.

Around nine o'clock, a bank of clouds rolled in and interrupted the viewing. For twenty minutes, nobody could see anything but gray. Mateo used the break to show the younger visitors how the telescope's mirrors gathered light.

When the clouds finally cleared, Ms. Haddad thanked the group. "Sharing the telescope with the neighborhood was good for everyone," she said. "Our visitors learned something, and so did we."

Mateo smiled and began packing the equipment for the ride home.$q$, 'draft')
